const cur = $('Group Stats & Build HTML').first().json;

let prevRow = null;
try {
  const rows = $('Read Previous Week').all();
  prevRow = rows.length ? rows[0].json : null;
} catch (e) {
  prevRow = null;
}

const parseJson = (v, fallback) => {
  if (v === null || v === undefined || v === '') return fallback;
  if (typeof v === 'object') return v;
  try { return JSON.parse(v); } catch (e) { return fallback; }
};

const prev = prevRow ? {
  totalIssues: Number(prevRow.total_issues) || 0,
  byType: parseJson(prevRow.by_type, { Bug: 0, Task: 0, Feature: 0, 'needs-triage': 0 }),
  byAuthor: parseJson(prevRow.by_author, {})
} : null;

const delta = {
  totalIssues: prev ? cur.totalIssues - prev.totalIssues : null,
  byType: Object.fromEntries(
    Object.keys(cur.byType).map(k => [k, prev ? cur.byType[k] - (prev.byType[k] || 0) : null])
  )
};

const prompt = `Ты — аналитик проекта. Составь краткий (3–4 предложения) деловой комментарий недели по статистике GitHub Issues на русском языке.

Текущая неделя (${cur.week_start} — ${cur.week_end}):
- Всего новых задач: ${cur.totalIssues}
- По типам: ${JSON.stringify(cur.byType)}

Прошлая неделя:
${prev ? `- Всего: ${prev.totalIssues}\n- По типам: ${JSON.stringify(prev.byType)}` : '- Данных за прошлую неделю нет (первый запуск)'}

Δ к прошлой неделе:
${prev ? `- Всего: ${delta.totalIssues}\n- По типам: ${JSON.stringify(delta.byType)}` : '- Δ не рассчитывается'}

Опиши динамику: что выросло, что упало, на что обратить внимание. Не выдумывай цифры, используй только данные выше. Без заголовков и списков — сплошной текст.`;

return [{
  json: {
    ...cur,
    prev,
    delta,
    prompt
  }
}];

const cur = $('Compute Delta & Build Prompt').first().json;
const aiText = $('AI Agent').first().json.output
const aiComment = (typeof aiText === 'string' ? aiText : JSON.stringify(aiText)).trim() || 'AI-комментарий недоступен.';

const delta = cur.delta || { totalIssues: null, byType: {} };
const prev = cur.prev;

const fmtDelta = (d) => {
  if (d === null || d === undefined) return '—';
  if (d > 0) return `+${d}`;
  return `${d}`;
};
const deltaColor = (d) => {
  if (d === null || d === undefined) return '#666';
  if (d > 0) return '#c0392b';
  if (d < 0) return '#27ae60';
  return '#333';
};

const typeRows = Object.entries(cur.byType)
  .map(([type, count]) => `<tr><td style="padding:8px;border:1px solid #ddd;"><b>${type}</b></td><td style="padding:8px;border:1px solid #ddd;text-align:center;">${count}</td></tr>`)
  .join('');

const deltaRows = Object.entries(delta.byType)
  .map(([type, d]) => `<tr><td style="padding:8px;border:1px solid #ddd;"><b>${type}</b></td><td style="padding:8px;border:1px solid #ddd;text-align:center;color:${deltaColor(d)};"><b>${fmtDelta(d)}</b></td></tr>`)
  .join('');

const authorRows = Object.entries(cur.byAuthor || {})
  .sort((a, b) => b[1].total - a[1].total)
  .map(([author, stats]) => `
    <tr>
      <td style="padding:8px;border:1px solid #ddd;">@${author}</td>
      <td style="padding:8px;border:1px solid #ddd;text-align:center;">${stats.Bug}</td>
      <td style="padding:8px;border:1px solid #ddd;text-align:center;">${stats.Task}</td>
      <td style="padding:8px;border:1px solid #ddd;text-align:center;">${stats.Feature}</td>
      <td style="padding:8px;border:1px solid #ddd;text-align:center;">${stats['needs-triage']}</td>
      <td style="padding:8px;border:1px solid #ddd;text-align:center;"><b>${stats.total}</b></td>
    </tr>`)
  .join('') || '<tr><td colspan="6" style="padding:8px;border:1px solid #ddd;text-align:center;">За прошедшую неделю новых задач не создавалось</td></tr>';

const prevLine = prev
  ? `<p style="color:#666;">Прошлая неделя: всего <b>${prev.totalIssues}</b> задач. Δ всего: <b style="color:${deltaColor(delta.totalIssues)};">${fmtDelta(delta.totalIssues)}</b></p>`
  : `<p style="color:#666;">Данных за прошлую неделю нет — это первый запуск, Δ не рассчитывается.</p>`;

const htmlReport = `
<div style="font-family: Arial, sans-serif; color: #333; max-width: 650px;">
  <h2>Еженедельный отчёт по GitHub Issues</h2>
  <p>Период: <b>${cur.week_start}</b> — <b>${cur.week_end}</b></p>
  <p>Всего новых задач за неделю: <b>${cur.totalIssues}</b></p>
  ${prevLine}

  <h3>1. Статистика по типам</h3>
  <table style="border-collapse: collapse; width: 100%; margin-bottom: 24px;">
    <thead>
      <tr style="background-color: #f4f6f8;">
        <th style="padding:8px;border:1px solid #ddd;text-align:left;">Тип (Label)</th>
        <th style="padding:8px;border:1px solid #ddd;text-align:center;">Количество</th>
      </tr>
    </thead>
    <tbody>${typeRows}</tbody>
  </table>

  <h3>2. Δ к прошлой неделе</h3>
  <table style="border-collapse: collapse; width: 100%; margin-bottom: 24px;">
    <thead>
      <tr style="background-color: #f4f6f8;">
        <th style="padding:8px;border:1px solid #ddd;text-align:left;">Тип (Label)</th>
        <th style="padding:8px;border:1px solid #ddd;text-align:center;">Δ</th>
      </tr>
    </thead>
    <tbody>${deltaRows}</tbody>
  </table>

  <h3>3. Активность по авторам</h3>
  <table style="border-collapse: collapse; width: 100%; margin-bottom: 24px;">
    <thead>
      <tr style="background-color: #f4f6f8;">
        <th style="padding:8px;border:1px solid #ddd;text-align:left;">Автор</th>
        <th style="padding:8px;border:1px solid #ddd;text-align:center;">Bug</th>
        <th style="padding:8px;border:1px solid #ddd;text-align:center;">Task</th>
        <th style="padding:8px;border:1px solid #ddd;text-align:center;">Feature</th>
        <th style="padding:8px;border:1px solid #ddd;text-align:center;">Triage</th>
        <th style="padding:8px;border:1px solid #ddd;text-align:center;">Всего</th>
      </tr>
    </thead>
    <tbody>${authorRows}</tbody>
  </table>

  <h3>4. AI-комментарий недели</h3>
  <div style="padding:12px 16px;background:#f9f9f9;border-left:4px solid #4a90d9;line-height:1.5;">
    ${aiComment.replace(/\n/g, '<br>')}
  </div>
</div>
`;

return [{
  json: {
    subject: `GitHub Weekly Report — ${cur.week_start} / ${cur.week_end}`,
    totalIssues: cur.totalIssues,
    byType: cur.byType,
    byAuthor: cur.byAuthor,
    delta: cur.delta,
    aiComment,
    htmlReport
  }
}];

const weekStart = $now.startOf('week');
const weekEnd = $now.endOf('week');

const getIssues = (nodeName) => {
  try {
    return $(nodeName).all()
      .map(i => i.json)
      .filter(item => item && item.id && !item.pull_request && new Date(item.created_at) >= new Date(weekStart.toISO()));
  } catch (e) {
    return [];
  }
};

const groups = {
  Bug: getIssues('Get Bugs1'),
  Task: getIssues('Get Tasks1'),
  Feature: getIssues('Get Features1'),
  'needs-triage': getIssues('Get Needs Triage1')
};

const byType = {
  Bug: groups.Bug.length,
  Task: groups.Task.length,
  Feature: groups.Feature.length,
  'needs-triage': groups['needs-triage'].length
};

const byAuthor = {};
const seenIds = new Set();

for (const [type, issues] of Object.entries(groups)) {
  for (const issue of issues) {
    const author = issue.user?.login || 'unknown';
    if (!byAuthor[author]) {
      byAuthor[author] = { Bug: 0, Task: 0, Feature: 0, 'needs-triage': 0, total: 0 };
    }
    byAuthor[author][type] += 1;

    if (!seenIds.has(`${author}_${issue.id}`)) {
      seenIds.add(`${author}_${issue.id}`);
      byAuthor[author].total += 1;
    }
  }
}

const totalIssues = Object.values(byType).reduce((a, b) => a + b, 0);

return [{
  json: {
    week_start: weekStart.toISODate(),
    week_end: weekEnd.toISODate(),
    totalIssues,
    byType,
    byAuthor
  }
}];
